Here's a basic outline of the code structure for a snake game in C using SDL:

```c
#include <stdio.h>
#include <stdlib.h>
#include <SDL2/SDL.h>

// Define constants for game settings
#define BOARD_WIDTH 20
#define BOARD_HEIGHT 15
#define SNAKE_SIZE 20
#define FOOD_SIZE 20

// Define structures for game objects
typedef struct {
    int x, y;
} Point;

typedef struct {
    Point *body;
    int len;
    int dir;
} Snake;

typedef struct {
    int x, y;
} Food;

// Define functions for game logic
void init_snake(Snake *snake);
void move_snake(Snake *snake);
void eat_food(Snake *snake, Food *food);

// Define functions for graphics rendering
void init_sdl(SDL_Window **window, SDL_Renderer **renderer);
void render_board(SDL_Renderer *renderer);
void render_snake(SDL_Renderer *renderer, Snake *snake);
void render_food(SDL_Renderer *renderer, Food *food);

int main(int argc, char *argv[]) {
    SDL_Window *window;
    SDL_Renderer *renderer;

    // Initialize SDL
    init_sdl(&window, &renderer);

    // Initialize game objects
    Snake snake;
    Food food;

    // Initialize game loop
    int running = 1;
    int score = 0;

    while (running) {
        // Handle user input
        SDL_Event event;
        while (SDL_PollEvent(&event)) {
            if (event.type == SDL_QUIT) {
                running = 0;
            } else if (event.type == SDL_KEYDOWN) {
                switch (event.key.keysym.sym) {
                    case SDLK_LEFT:
                        snake.dir = -1;
                        break;
                    case SDLK_RIGHT:
                        snake.dir = 1;
                        break;
                    case SDLK_UP:
                        snake.dir = -BOARD_WIDTH;
                        break;
                    case SDLK_DOWN:
                        snake.dir = BOARD_WIDTH;
                        break;
                }
            }
        }

        // Update game logic
        move_snake(&snake);
        eat_food(&snake, &food);

        // Render game graphics
        SDL_RenderClear(renderer);
        render_board(renderer);
        render_snake(renderer, &snake);
        render_food(renderer, &food);
        SDL_RenderPresent(renderer);

        // Check for game over condition
        if (snake.body[0].x < 0 || snake.body[0].x >= BOARD_WIDTH || snake.body[0].y < 0 || snake.body[0].y >= BOARD_HEIGHT) {
            running = 0;
        }

        // Update score
        score++;
    }

    // Clean up SDL resources
    SDL_DestroyRenderer(renderer);
    SDL_DestroyWindow(window);
    SDL_Quit();

    printf("Game over! Your score was %d.\n", score);

    return 0;
}

void init_sdl(SDL_Window **window, SDL_Renderer **renderer) {
    if (SDL_Init(SDL_INIT_VIDEO) < 0) {
        printf("Failed to initialize SDL: %s\n", SDL_GetError());
        exit(1);
    }

    *window = SDL_CreateWindow("Snake Game",
                                SDL_WINDOWPOS_UNDEFINED,
                                SDL_WINDOWPOS_UNDEFINED,
                                BOARD_WIDTH * SNAKE_SIZE,
                                BOARD_HEIGHT * SNAKE_SIZE,
                                SDL_WINDOW_SHOWN);

    if (!*window) {
        printf("Failed to create window: %s\n", SDL_GetError());
        exit(1);
    }

    *renderer = SDL_CreateRenderer(*window, -1, SDL_RENDERER_ACCELERATED);
    if (!*renderer) {
        printf("Failed to create renderer: %s\n", SDL_GetError());
        exit(1);
    }
}

void render_board(SDL_Renderer *renderer) {
    // Render background
    SDL_SetRenderDrawColor(renderer, 0x00, 0x00, 0x00, 0xFF);
    SDL_RenderFillRect(renderer, NULL);

    // Render tiles
    for (int I = 0; I < BOARD_WIDTH; i++) {
        for (int j = 0; j < BOARD_HEIGHT; j++) {
            SDL_Rect tile = {i * SNAKE_SIZE, j * SNAKE_SIZE, SNAKE_SIZE, SNAKE_SIZE};
            SDL_SetRenderDrawColor(renderer, 0x00, 0x80, 0x00, 0xFF);
            SDL_RenderFillRect(renderer, &tile);
        }
    }
}

void render_snake(SDL_Renderer *renderer, Snake *snake) {
    // Render snake body
    SDL_SetRenderDrawColor(renderer, 0xFF, 0xFF, 0x00, 0xFF);
    for (int I = 1; I < snake->len; i++) {
        SDL_Rect body = {snake->body[i - 1].x * SNAKE_SIZE, snake->body[i - 1].y * SNAKE_SIZE, SNAKE_SIZE, SNAKE_SIZE};
        SDL_RenderFillRect(renderer, &body);
    }

    // Render snake head
    SDL_Rect head = {snake->body[0].x * SNAKE_SIZE, snake->body[0].y * SNAKE_SIZE, SNAKE_SIZE, SNAKE_SIZE};
    SDL_SetRenderDrawColor(renderer, 0xFF, 0x00, 0x00, 0xFF);
    SDL_RenderFillRect(renderer, &head);
}

void render_food(SDL_Renderer *renderer, Food *food) {
    SDL_Rect food_rect = {food->x * SNAKE_SIZE, food->y * SNAKE_SIZE, FOOD_SIZE, FOOD_SIZE};
    SDL_SetRenderDrawColor(renderer, 0x00, 0xFF, 0x00, 0xFF);
    SDL_RenderFillRect(renderer, &food_rect);
}
```

Note that this is just a basic outline and you'll need to add more functionality and graphics rendering code to fully implement a snake game in C using SDL. Also, be sure to read the SDL documentation for a more detailed guide on how to use the library.

