public static boolean isThreePower(int n) {
    if (n < 0 || n > Math.pow(3, 31) - 1) { // Check input range constraint
        throw new IllegalArgumentException("Input value should be between -231 and 231 - 1");
    }
    double log3 = Math.log(n) / Math.log(3);
