    std::cout << "Enter the name of the input file: ";
    std::cin >> filename;

    std::cout << "Enter the word to search for: ";
    std::cin >> word;

    // open the input file
    std::ifstream file(filename);
    if (!file.is_open()) {
        std::cerr << "Error: could not open file " << filename << std::endl;
        return 1; // indicate failure
    }

    // read the file line by line and count occurrences of the search word
    std::string line;
    while (std::getline(file, line)) {
        std::size_t pos = 0;
        while ((pos = line.find(word, pos)) != std::string::npos) {
            count++; // increment count if search word is found
            pos += word.length(); // move the search position forward
        }
    }

    // close the input file
    file.close();

    // output the result
    std::cout << "The word '" << word << "' appears " << count << " times in " << filename << std::endl;

    return 0; // indicate success
}
```

Note that this program assumes that the input file is plain text (i.e., no binary data), and that the search word is a simple string (i.e., not a regular expression). If you need more advanced text processing features, you may want to consider using a library like Boost.Regex or std::regex.

